from pipeline.herramientas.control import mes_ya_procesado

def debe_ingestar(corrida: Corrida, tabla: str, mes: str) -> bool:
    ya_esta_registrado = mes_ya_procesado(corrida, tabla, CAPA, mes)
    if ya_esta_registrado:
        return False
    return True

USE ROLE BIGDATA_DEV;
USE WAREHOUSE BIGDATA_WH;
USE DATABASE BIGDATA;

SELECT TABLA, CAPA, MES, FILAS, LEIDAS, COMPUTO, LIMITE, REPROCESAR
FROM BIGDATA.CONTROL_DEV.WATERMARK
ORDER BY INICIO;

USE ROLE BIGDATA_DEV;
USE WAREHOUSE BIGDATA_WH;
USE DATABASE BIGDATA;

CREATE TABLE IF NOT EXISTS BIGDATA.DEV.TARIFA_POR_MILLA_BARRIO (
  FECHA DATE, BOROUGH VARCHAR, FRANJA VARCHAR,
  VIAJES NUMBER(38,0), DISTANCIA_TOTAL_MI FLOAT,
  INGRESO_TOTAL FLOAT, TARIFA_POR_MILLA FLOAT);

USE ROLE BIGDATA_DEV;
USE WAREHOUSE BIGDATA_WH;
USE DATABASE BIGDATA;

SELECT COUNT(*) AS filas, SUM(VIAJES) AS viajes, MIN(FECHA), MAX(FECHA)
FROM BIGDATA.DEV.TARIFA_POR_MILLA_BARRIO;

USE ROLE BIGDATA_DEV;
USE WAREHOUSE BIGDATA_WH;
USE DATABASE BIGDATA;

SELECT TABLA, CAPA, MES, FILAS, LEIDAS, REPROCESAR, INICIO
FROM BIGDATA.CONTROL_DEV.WATERMARK
QUALIFY ROW_NUMBER() OVER (PARTITION BY TABLA, CAPA, MES
